import fallbacks from "./display-type-fallbacks.json";

/**
 * `"gfx:displayType"` pairs whose generated module breaks under the
 * server's canonical displayType. Generated by
 * `scripts/audit-spell-display-types.ts`; shrinks as modules are fixed.
 */
const BROKEN_UNDER_CANONICAL: ReadonlySet<string> = new Set(fallbacks.pairs);

/**
 * The displayType a visual plays with.
 *
 * 1.29 takes it from the cast (`GA;300`, `sorts.spriteInfos`): it belongs
 * to the spell, and one gfx serves several (gfx 503 is 11 for
 * Ralentissement, 10 for Protection Aveuglante). So the server's value
 * wins over the one each generated module hard-codes — except for a pair
 * the audit found broken under it, where the module was written against
 * its own guess and is kept on it until fixed (QA-181). Without either,
 * the caller's default applies.
 */
export function effectiveDisplayType(
  gfx: number,
  wire: number | undefined,
  own: number | undefined
): number | undefined {
  if (wire === undefined || wire <= 0) {
    return own;
  }
  if (own !== undefined && BROKEN_UNDER_CANONICAL.has(`${gfx}:${wire}`)) {
    return own;
  }
  return wire;
}
